{"path": "/workspace/dump_case.py", "content": "import sqlite3, sys

con = sqlite3.connect('/workspace/cms/ridgeline_cms.db')
con.row_factory = sqlite3.Row

def dump(case_id):
    print('#'*70)
    print('CASE:', case_id)
    for r in con.execute('SELECT * FROM cases WHERE case_id=?', (case_id,)):
        for k in r.keys():
            print(f'  {k}: {r[k]}')
    print('--- SUBJECTS ---')
    subs = [dict(r) for r in con.execute('SELECT * FROM subjects WHERE case_id=?', (case_id,))]
    for s in subs:
        print(s)
    print('--- ADDRESS HISTORY ---')
    for s in subs:
        for r in con.execute('SELECT * FROM address_history WHERE subject_id=?', (s['subject_id'],)):
            print(dict(r))
    print('--- PHONES ---')
    for s in subs:
        for r in con.execute('SELECT * FROM phones WHERE subject_id=?', (s['subject_id'],)):
            print(dict(r))
    print('--- VEHICLES ---')
    for s in subs:
        for r in con.execute('SELECT * FROM vehicles WHERE subject_id=?', (s['subject_id'],)):
            print(dict(r))
    print('--- EMPLOYMENT ---')
    for s in subs:
        for r in con.execute('SELECT * FROM employment WHERE subject_id=?', (s['subject_id'],)):
            print(dict(r))
    print('--- SOCIAL MEDIA ---')
    for s in subs:
        for r in con.execute('SELECT * FROM social_media WHERE subject_id=?', (s['subject_id'],)):
            print(dict(r))
    print('--- NOTES ---')
    for r in con.execute("SELECT * FROM notes WHERE case_id=? ORDER BY date", (case_id,)):
        print(dict(r))
    print('--- FIELD LOGS ---')
    for r in con.execute("SELECT * FROM field_logs WHERE case_id=? ORDER BY date, time", (case_id,)):
        print(dict(r))
    print()

for cid in sys.argv[1:]:
    dump(cid)
"}

